const API = import.meta.env.VITE_API_URL || 'http://localhost:3000/api';
async function publicRequest(path: string, init: RequestInit = {}) { const response = await fetch(`${API}${path}`, { ...init, headers: { 'Content-Type': 'application/json', ...(init.headers || {}) } }); const body = await response.json().catch(() => ({})); if (!response.ok) { const raw = body?.message; const message = typeof raw === 'string' ? raw : raw?.message || raw?.error || body?.error || 'No se pudo abrir el enlace.'; throw new Error(message); } return body; }

const documentTypeLabels: Record<string, string> = { estimate: 'Cotización', quotation: 'Cotización', quote: 'Cotización', 'sales-order': 'Orden de venta', order: 'Orden de venta', invoice: 'Factura', 'recurring-invoice': 'Factura recurrente', 'payment-received': 'Pago recibido', payment: 'Pago recibido', 'sales-return': 'Devolución', return: 'Devolución', 'credit-note': 'Nota de crédito', creditnote: 'Nota de crédito' };
const statusLabels: Record<string, string> = { DRAFT: 'Borrador', PENDING: 'Pendiente', SENT: 'Enviada', APPROVED: 'Aprobada', PAID: 'Pagada', PARTIAL: 'Pago parcial', OVERDUE: 'Vencida', CANCELLED: 'Cancelada', COMPLETED: 'Completada', ACTIVE: 'Activa', INACTIVE: 'Inactiva', SHIPPED: 'Enviada', DELIVERED: 'Entregada', REFUNDED: 'Reembolsada', VOID: 'Anulada', OPEN: 'Abierta', CLOSED: 'Cerrada' };
const paymentMethodLabels: Record<string, string> = { CASH: 'Efectivo', CARD: 'Tarjeta', TRANSFER: 'Transferencia bancaria', CHECK: 'Cheque', CREDIT: 'Crédito', OTHER: 'Otro' };
const currencyLabels: Record<string, string> = { NIO: 'Córdobas nicaragüenses (NIO)', USD: 'Dólares estadounidenses (USD)', EUR: 'Euros (EUR)' };
const labelFor = (value: unknown, labels: Record<string, string>, fallback = '—') => {
  const raw = String(value || '').trim();
  const normalized = raw.toLowerCase().replace(/_/g, '-');
  return labels[raw] || labels[normalized] || labels[raw.toUpperCase()] || fallback;
};
const formatDate = (value: unknown) => value ? new Intl.DateTimeFormat('es-NI', { dateStyle: 'medium' }).format(new Date(String(value))) : '—';
const formatAmount = (value: unknown, currency = 'NIO') => `${new Intl.NumberFormat('es-NI', { minimumFractionDigits: 2, maximumFractionDigits: 2 }).format(Number(value || 0))} ${currency}`;
const portalPdfTypes: Record<string, 'estimate' | 'order' | 'invoice' | 'recurring' | 'payment' | 'return' | 'credit-note'> = { estimate: 'estimate', 'sales-order': 'order', invoice: 'invoice', 'recurring-invoice': 'recurring', 'payment-received': 'payment', 'sales-return': 'return', 'credit-note': 'credit-note' };
const portalDesignKeys: Record<string, string> = { estimate: 'ventas.estimate', 'sales-order': 'ventas.order', invoice: 'ventas.invoice', 'recurring-invoice': 'ventas.recurring', 'payment-received': 'ventas.payment', 'sales-return': 'ventas.return', 'credit-note': 'ventas.credit-note' };
const documentDateKey = (value: unknown) => { if (!value) return ''; const date = new Date(String(value)); return Number.isNaN(date.getTime()) ? '' : date.toISOString().slice(0, 10); };
const portalColor = (value: unknown, fallback: string) => typeof value === 'string' && /^#[0-9a-f]{6}$/i.test(value) ? value : fallback;

function AccessShell({ children, company }: { children: React.ReactNode; company?: any }) { const isLight = company?.portalDefaultTheme === 'light'; const primary = portalColor(company?.portalPrimaryColor, isLight ? '#059669' : '#10b981'); const card = isLight ? '#ffffff' : portalColor(company?.portalAccentColor, '#0f172a'); const border = isLight ? '#e2e8f0' : '#1e293b'; const text = isLight ? '#0f172a' : '#f8fafc'; const muted = isLight ? '#64748b' : '#94a3b8'; const bg = isLight ? '#f8fafc' : '#020617'; const subtle = isLight ? '#f1f5f9' : '#0b1220'; return <main style={{ '--portal-primary': primary, '--portal-bg': bg, '--portal-card': card, '--portal-border': border, '--portal-text': text, '--portal-muted': muted, '--portal-subtle': subtle, colorScheme: isLight ? 'light' : 'dark' } as React.CSSProperties} className={isLight ? "novahub-public-portal portal-light min-h-screen px-4 py-8" : "novahub-public-portal portal-dark min-h-screen px-4 py-8"}><style>{'.novahub-public-portal { background: var(--portal-bg); color: var(--portal-text); } .novahub-public-portal.portal-dark { background: #020617 !important; color: #f8fafc !important; } .novahub-public-portal.portal-light { background: var(--portal-bg) !important; color: var(--portal-text) !important; } .novahub-public-portal .bg-slate-950, .novahub-public-portal .bg-slate-950\\/40 { background-color: var(--portal-bg) !important; } .novahub-public-portal .bg-slate-900, .novahub-public-portal .bg-slate-900\\/90, .novahub-public-portal .portal-card { background: var(--portal-card) !important; background-color: var(--portal-card) !important; } .novahub-public-portal .bg-slate-800, .novahub-public-portal .bg-slate-800\\/50 { background-color: var(--portal-subtle) !important; } .novahub-public-portal .border-slate-800, .novahub-public-portal .border-slate-700 { border-color: var(--portal-border) !important; } .novahub-public-portal .text-slate-100, .novahub-public-portal .text-slate-300, .novahub-public-portal .text-white { color: var(--portal-text) !important; } .novahub-public-portal .text-slate-400, .novahub-public-portal .text-slate-500 { color: var(--portal-muted) !important; }'}</style><div className="mx-auto max-w-5xl"><header className="mb-6 flex items-center gap-3 rounded-2xl border bg-slate-900/90 p-5" style={{ borderColor: 'var(--portal-border)' }}><div className="flex size-11 shrink-0 items-center justify-center overflow-hidden rounded-xl" style={{ backgroundColor: primary + '26' }}><>{company?.logo ? <img src={company.logo} alt={'Logo de ' + (company.name || 'la empresa')} className="size-full object-contain p-1" /> : <ShieldCheck className="size-6 text-[var(--portal-primary)]" />}</></div><p className="flex-1 text-lg font-semibold">{company?.name || 'Acceso seguro'}</p></header>{children}<p className="mt-6 text-center text-xs text-[var(--portal-muted)]">Este enlace es temporal y está protegido por NovaHub.</p></div></main>; }

function OtpForm({ token, mode, maskedTarget, onVerified }: { token: string; mode: 'document' | 'portal'; maskedTarget?: string | null; onVerified: (session: string) => void }) { const [challengeId, setChallengeId] = useState<string | null>(null); const [code, setCode] = useState(''); const [message, setMessage] = useState(''); const requestCode = async () => { try { const result = await publicRequest(`/public-access/${mode}/${token}/otp`, { method: 'POST' }); setChallengeId(result.challengeId); setMessage(result.devCode ? `Código de desarrollo: ${result.devCode}` : `Enviamos un código a ${result.maskedTarget}.`); } catch (error: any) { setMessage(error.message); } }; const verify = async () => { try { const result = await publicRequest(`/public-access/${mode}/${token}/verify`, { method: 'POST', body: JSON.stringify({ challengeId, code }) }); onVerified(result.sessionToken); } catch (error: any) { setMessage(error.message); } }; return <div className="mx-auto max-w-md rounded-2xl border border-slate-800 bg-slate-900 p-7"><LockKeyhole className="mb-4 size-8 text-emerald-400" /><h1 className="text-xl font-semibold">Verifica tu acceso</h1><p className="mt-2 text-sm text-slate-400">Por seguridad necesitamos confirmar tu identidad{maskedTarget ? ` en ${maskedTarget}` : ''}.</p>{message && <p className="mt-4 rounded-lg bg-slate-800 p-3 text-sm text-emerald-300">{message}</p>}{!challengeId ? <button onClick={requestCode} className="mt-6 w-full rounded-xl bg-emerald-500 px-4 py-3 font-semibold text-slate-950">Enviar código</button> : <div className="mt-6 space-y-3"><input value={code} onChange={e => setCode(e.target.value)} inputMode="numeric" maxLength={6} placeholder="Código de 6 dígitos" className="w-full rounded-xl border border-slate-700 bg-slate-950 px-4 py-3 outline-none focus:border-emerald-400" /><button onClick={verify} className="w-full rounded-xl bg-emerald-500 px-4 py-3 font-semibold text-slate-950">Continuar</button></div>}</div>; }

function DocumentView({ data, permissions }: { data: any; permissions: any }) { const { company, document, customer, items } = data; return <AccessShell company={company}><section className="rounded-2xl border border-slate-800 bg-white p-6 text-slate-900 shadow-2xl print:shadow-none"><div className="flex justify-between border-b border-slate-200 pb-5"><div><h1 className="text-2xl font-bold text-emerald-600">{company.name}</h1><p className="text-sm text-slate-500">{labelFor(data.type, documentTypeLabels, 'Documento')}</p></div><div className="text-right"><h2 className="text-xl font-bold uppercase">{document.number}</h2><p className="text-sm text-slate-500">Fecha: {formatDate(document.date)}</p><p className="text-sm text-slate-500">Estado: {labelFor(document.status, statusLabels, 'Emitido')}</p></div></div><div className="grid gap-4 py-5 sm:grid-cols-2"><div><p className="text-xs font-bold uppercase text-emerald-600">Datos del cliente</p><p className="font-semibold">{customer.name}</p><p className="text-sm text-slate-500">{customer.razonSocial || ''}</p><p className="text-sm text-slate-500">{customer.email || customer.phone || ''}</p><p className="text-sm text-slate-500">{customer.address || ''}{customer.city ? ` · ${customer.city}` : ''}</p></div><div className="text-left sm:text-right"><p className="text-xs font-bold uppercase text-slate-500">Información comercial</p><p className="text-sm">Código: {customer.code || '—'}</p><p className="text-sm">Identificación fiscal: {customer.ruc || customer.taxId || '—'}</p></div></div><div className="overflow-x-auto"><table className="w-full text-sm"><thead><tr className="bg-emerald-500 text-white"><th className="p-3 text-left">Descripción</th><th className="p-3 text-right">Cantidad</th><th className="p-3 text-right">Precio unitario</th><th className="p-3 text-right">Total</th></tr></thead><tbody>{items.length ? items.map((item: any, index: number) => <tr key={index} className="border-b border-slate-200"><td className="p-3">{item.description}</td><td className="p-3 text-right">{item.quantity}</td><td className="p-3 text-right">{formatAmount(item.unitPrice, document.currency)}</td><td className="p-3 text-right">{formatAmount(item.total, document.currency)}</td></tr>) : <tr><td colSpan={4} className="p-5 text-center text-slate-500">Sin líneas de detalle</td></tr>}</tbody></table></div><div className="mt-6 ml-auto max-w-xs space-y-2 text-right"><p>Subtotal: {formatAmount(document.subtotal, document.currency)}</p><p>Impuestos: {formatAmount(document.taxAmount, document.currency)}</p><p className="border-t border-slate-200 pt-2 text-lg font-bold text-emerald-600">Total: {formatAmount(document.total, document.currency)}</p></div><div className="mt-8 flex gap-3 print:hidden">{permissions.print && <button onClick={() => window.print()} className="inline-flex items-center gap-2 rounded-xl border border-slate-300 px-4 py-2 font-semibold"><Printer className="size-4" /> Imprimir</button>}{permissions.download && <button onClick={() => window.print()} className="rounded-xl bg-emerald-600 px-4 py-2 font-semibold text-white">Descargar PDF</button>}</div></section></AccessShell>; }

